create table if not exists public.friend_link_categories (id bigint generated by default as identity primary key, slug varchar(60) not null unique, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.friend_link_category_translations (id bigint generated by default as identity primary key, category_id bigint not null references public.friend_link_categories(id) on delete cascade, locale_id bigint not null references public.locales(id) on delete cascade, name varchar(60) not null, created_at timestamptz not null default now(), unique(category_id, locale_id));
create table if not exists public.friend_links (id bigint generated by default as identity primary key, name varchar(120) not null, url varchar(500) not null, normalized_url varchar(500) not null, domain varchar(200) not null, description varchar(500) not null default '', logo_media_id bigint references public.media(id) on delete set null, external_logo_url varchar(500), category_id bigint references public.friend_link_categories(id) on delete set null, status varchar(20) not null default 'active', featured boolean not null default false, sort_order integer not null default 0, backlink_required boolean not null default false, backlink_status varchar(20) not null default 'unknown', backlink_url varchar(500), backlink_last_checked_at timestamptz, backlink_last_found_at timestamptz, backlink_failure_count integer not null default 0, nofollow boolean not null default false, open_in_new_tab boolean not null default true, source varchar(20) not null default 'admin', submission_id bigint, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.friend_link_submissions (id bigint generated by default as identity primary key, site_name varchar(120) not null, site_url varchar(500) not null, normalized_url varchar(500) not null, domain varchar(200) not null, description varchar(500) not null default '', logo_url varchar(500), contact_name varchar(80), contact_email varchar(200), backlink_url varchar(500), status varchar(20) not null default 'pending', backlink_status varchar(20) not null default 'unknown', backlink_checked_at timestamptz, backlink_found_url varchar(500), site_status varchar(20) not null default 'unknown', site_http_status integer, site_title_detected varchar(300), reviewer_id bigint references public.users(id) on delete set null, reviewed_at timestamptz, rejection_reason varchar(300), admin_note varchar(500), submit_ip_hash varchar(64), user_agent varchar(300), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.friend_link_checks (id bigint generated by default as identity primary key, friend_link_id bigint not null references public.friend_links(id) on delete cascade, check_type varchar(20) not null, status varchar(20) not null, http_status integer, found_url varchar(500), details_json text, checked_at timestamptz not null default now());
create index if not exists friend_link_categories_slug_idx on public.friend_link_categories(slug);
create index if not exists friend_link_cat_tr_locale_idx on public.friend_link_category_translations(locale_id);
create index if not exists friend_links_status_idx on public.friend_links(status, sort_order);
create index if not exists friend_links_domain_idx on public.friend_links(domain);
create index if not exists friend_link_subs_status_idx on public.friend_link_submissions(status, created_at);
create index if not exists friend_link_subs_domain_idx on public.friend_link_submissions(domain);
create index if not exists friend_link_checks_link_idx on public.friend_link_checks(friend_link_id, checked_at);
alter table public.friend_link_categories enable row level security;
alter table public.friend_link_category_translations enable row level security;
alter table public.friend_links enable row level security;
alter table public.friend_link_submissions enable row level security;
alter table public.friend_link_checks enable row level security;
revoke all on table public.friend_link_categories, public.friend_link_category_translations, public.friend_links, public.friend_link_submissions, public.friend_link_checks from anon, authenticated;
